from collections import deque

def shortest_hops(graph, start, target):
    queue = deque([start])
    parent = {start: None}

    while queue:
        node = queue.popleft()
        if node == target:
            path = []
            while node is not None:
                path.append(node)
                node = parent[node]
            return list(reversed(path))
        for neighbor in graph.get(node, []):
            if neighbor not in parent:
                parent[neighbor] = node
                queue.append(neighbor)
    return None

graph = {'start': ['loops', 'functions'], 'loops': ['files'], 'functions': ['files'], 'files': []}
print(shortest_hops(graph, 'start', 'files'))

