from collections import deque

def reachable(graph, start, target):
    queue = deque([start])
    visited = {start}
    while queue:
        node = queue.popleft()
        if node == target:
            return True
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
    return False

graph = {'start': ['loops'], 'loops': ['files'], 'files': ['start'], 'apis': []}
print(reachable(graph, 'start', 'files'))
print(reachable(graph, 'start', 'apis'))
